(function(){
'use strict';
if(typeof DATA==='undefined' || typeof PUBLIC_DATA==='undefined') return;
const S=v=>(v==null?'':String(v));
const N=v=>S(v).toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const has=(v,x)=>N(v).includes(N(x));

// 1) Кириллина: это назначение является фиксированным. Не меняем ни день, ни время,
// ни дисциплину, ни аудиторию. Если более ранние слои оставили дубль/неполную строку,
// сводим её к единственной точной записи Вт 13:00, ауд.228.
const K='кириллина светлана алексеевна';
const kirDisc='История религии изучаемой страны (региона) (Исламоведение) — лекции';
let kir=null;
for(let i=DATA.length-1;i>=0;i--){
  const r=DATA[i]; if(!r||N(r.teacher)!==K) continue;
  if(has(r.discipline,'история религии изучаемой страны')||has(r.discipline,'исламоведение')){
    if(!kir) kir=r; else DATA.splice(i,1);
  }
}
if(!kir){
  kir={group:'4 курс — история — арабский; 4 курс — история — пушту; 4 курс — история — суахили; 4 курс — история — хауса; 4 курс — политика — арабский; 4 курс — филология — арабский; 4 курс — филология — персидский; 4 курс — филология — турецкий',course:'4 бакалавриат',direction:'общий поток',teacher:'Кириллина Светлана Алексеевна'};
  DATA.push(kir);
}
kir.day='Вт'; kir.time='13:00'; kir.discipline=kirDisc; kir.room_hint='228';
kir.quality='01.09.2026: по прямому указанию время, занятие и аудитория Кириллиной зафиксированы без изменений: Вт 13:00, «История религии изучаемой страны (региона) (Исламоведение) — лекции», ауд.228. Конфликт снимается переносом аудитории другого занятия, а не этой лекции.';

// 2) Реальный конфликт на скриншоте был аудиторным: в 228 одновременно стояло
// «Социально-политическое развитие Южной Азии» для 4 курса хинди. День и время
// этого курса сохраняем, меняем только аудиторию на 415 для всех трёх совместных лекторов.
const southTeachers=new Set(['бочковская анна викторовна','сафронова александра львовна','филимонова алина левоновна']);
DATA.forEach(r=>{
  if(!r) return;
  if(S(r.day).trim()==='Вт' && S(r.time).trim()==='13:00' &&
     has(r.discipline,'социально-политическое развитие южной азии') && southTeachers.has(N(r.teacher))){
    r.room_hint='415';
    r.quality='01.09.2026: время Вт 13:00 и состав курса сохранены; аудитория изменена 228 → 415 исключительно для снятия двойного бронирования с фиксированной лекцией С.А. Кириллиной в ауд.228.';
  }
});

// 3) Ардашникова: карточка «Спецсеминар по профилю подготовки» не должна
// оставаться в разделе «уточняется». Среда 14:40 исключена правилом МФК.
// Исторический пятничный вариант был рабочим, но 14:40 занят языковым блоком,
// поэтому ставим следующий разрешённый слот Пт 16:20. Ауд.415 в этот момент
// используется как малая учебная аудитория для профильного семинара.
const A='ардашникова анна наумовна';
function isArdSem(r){
  return r && N(r.teacher)===A && S(r.course).trim()==='4 бакалавриат' &&
    has(r.discipline,'спецсеминар по профилю подготовки') &&
    (N(r.group)==='23б/ф323/7'||has(r.group,'23б/ф323/7'));
}
for(let i=DATA.length-1;i>=0;i--){if(isArdSem(DATA[i])) DATA.splice(i,1);}
DATA.push({
  group:'23Б/Ф323/7',course:'4 бакалавриат',direction:'Филология',day:'Пт',time:'16:20',
  discipline:'Спецсеминар по профилю подготовки (проводит раздельно у литературоведов Ардашникова, у лингвистов В.Б. Иванов).',
  extra:'литературоведы; 2 ч/нед.',teacher:'Ардашникова Анна Наумовна',room_hint:'415',
  quality:'01.09.2026: финальная фиксация без статуса «уточняется». По актуальной заявке А.Н. Ардашниковой допустимы Вт/Ср/Чт/Пт и 10:40/13:00/14:40/16:20. Прежний Ср 14:40 снят из-за общеуниверситетского блока МФК; Пт 14:40 занят действующим языковым блоком. Профильный семинар поставлен Пт 16:20, ауд.415.'
});

// Убираем созданный предыдущим временным патчем незапланированный дубль литературы
// Ардашниковой со статусом «уточняется»: в публичном расписании не должно быть
// отдельной карточки без дня/времени. Основная назначенная строка литературы сохраняется.
for(let i=DATA.length-1;i>=0;i--){
  const r=DATA[i];
  if(r && N(r.teacher)===A && has(r.discipline,'литература изучаемого региона') &&
     S(r.course).trim()==='3 бакалавриат' && (N(r.day)==='уточняется'||N(r.time)==='уточняется')) DATA.splice(i,1);
}

const rows=typeof isServiceRow==='function'?DATA.filter(r=>!isServiceRow(r)):DATA.slice();
PUBLIC_DATA.splice(0,PUBLIC_DATA.length,...rows);
try{if(typeof buildGroupItems==='function')buildGroupItems();}catch(e){}
try{if(typeof buildBrowseList==='function')buildBrowseList();}catch(e){}
})();